export const Quillo = wordmark("Quillo", <><path d="M14 9a11 11 0 1 0 0 22h9V20A11 11 0 0 0 14 9Z" /></>);
export const Fernway = wordmark("Fernway", <><path d="M6 30c0-12 8-20 18-20 0 12-8 20-18 20Z" /></>);
